rollback.sql:
DELETE FROM system_settings WHERE setting_key LIKE 'resilience.circuitbreaker.%.slow-call-%'
   OR setting_key LIKE 'resilience.circuitbreaker.%.permitted-number-of-calls-in-half-open-state'
   OR setting_key LIKE 'resilience.circuitbreaker.%.automatic-transition-from-open-to-half-open-state';
